func main() {
}

var region string

cmd := &cobra.Command{
    Use: "deploy",
    Run: func(cmd *cobra.Command, args []string) {
        fmt.Println("deploying to", region)
    },
}

cmd.Flags().StringVarP(&region, "region", "r", "", "target region")
if err := cmd.MarkFlagRequired("region"); err != nil {
    fmt.Println(err)
    os.Exit(1)
}

if err := cmd.Execute(); err != nil {
    os.Exit(1)
}

